import re
from collections import deque
from typing import Any, Dict, List, Optional, Tuple


_SECTION_RE = re.compile(r"^\s*\[([^\]]+)\]")
_OPTION_RE = re.compile(r"^\s*(\d+)\.\s*(.*?)\s*(?:->\s*([^\s#]+))?\s*$")
_LINE_RE = re.compile(r"^\s*([^:]+):\s*(.*?)\s*(?:->\s*([^\s#]+))?\s*$")
_ARROW_RE = re.compile(r"->\s*([^\s#]+)\s*$")


def _parse_section_header(line: str) -> Optional[str]:
    m = _SECTION_RE.match(line)
    if not m:
        return None
    return m.group(1).strip()


def _parse_option_line(line: str) -> Optional[Tuple[str, Optional[str]]]:
    m = _OPTION_RE.match(line)
    if not m:
        return None
    text = m.group(2).strip()
    target = m.group(3).strip() if m.group(3) else None
    return text, target


def _parse_speaker_line(line: str) -> Optional[Tuple[str, str, Optional[str]]]:
    m = _LINE_RE.match(line)
    if not m:
        return None
    speaker = m.group(1).strip()
    text = m.group(2).strip()
    target = m.group(3).strip() if m.group(3) else None
    return speaker, text, target


def parse_script(text: str) -> Dict[str, Any]:
    """Parse a dialogue script into a graph dict of nodes/edges.

    Output format:
    {
      "nodes": [{"id":"","text":"","speaker":"","type":"line|choice|end"}, ...],
      "edges": [{"from":"","to":"","text":""}, ...]
    }
    """

    sections: List[Tuple[str, List[str]]] = []
    current_id: Optional[str] = None
    buf: List[str] = []

    for raw in text.splitlines():
        header_id = _parse_section_header(raw)
        if header_id is not None:
            if current_id is not None:
                sections.append((current_id, buf))
            current_id = header_id
            buf = []
            continue

        if current_id is None:
            continue
        buf.append(raw.rstrip("\n"))

    if current_id is not None:
        sections.append((current_id, buf))

    if not sections:
        raise ValueError("No sections found in script")

    start_id = sections[0][0]

    nodes_by_id: Dict[str, Dict[str, str]] = {}
    node_order: List[str] = []
    edges: List[Dict[str, str]] = []
    referenced: set[str] = set()

    for node_id, lines in sections:
        if node_id in nodes_by_id:
            raise ValueError(f"Duplicate node id: {node_id}")

        non_empty = [ln.strip() for ln in lines if ln.strip()]
        option_lines: List[Tuple[str, Optional[str]]] = []
        prompt_lines: List[str] = []

        for ln in non_empty:
            opt = _parse_option_line(ln)
            if opt is not None:
                option_lines.append(opt)
            else:
                prompt_lines.append(ln)

        if option_lines:
            node_type = "choice"
            speaker = ""
            node_text = ""

            if prompt_lines:
                parsed = _parse_speaker_line(prompt_lines[0])
                if parsed is not None:
                    speaker, node_text, _ = parsed
                else:
                    node_text = prompt_lines[0]

            for opt_text, target in option_lines:
                to_id = target or "End"
                edges.append({"from": node_id, "to": to_id, "text": opt_text})
                referenced.add(to_id)
        else:
            node_type = "line"
            speaker = ""
            node_text = ""
            target: Optional[str] = None

            if non_empty:
                parsed = _parse_speaker_line(non_empty[0])
                if parsed is not None:
                    speaker, node_text, target = parsed
                else:
                    m = _ARROW_RE.search(non_empty[0])
                    if m:
                        target = m.group(1).strip()
                        node_text = non_empty[0][: m.start()].strip()
                    else:
                        node_text = non_empty[0].strip()

            if target:
                edges.append({"from": node_id, "to": target, "text": ""})
                referenced.add(target)

        nodes_by_id[node_id] = {"id": node_id, "text": node_text, "speaker": speaker, "type": node_type}
        node_order.append(node_id)

    if "End" in referenced and "End" not in nodes_by_id:
        nodes_by_id["End"] = {"id": "End", "text": "", "speaker": "", "type": "end"}
        node_order.append("End")

    missing = sorted(t for t in referenced if t not in nodes_by_id)
    if missing:
        raise ValueError("Missing target node(s): " + ", ".join(missing))

    graph = {
        "nodes": [nodes_by_id[nid] for nid in node_order],
        "edges": edges,
        "start": start_id,
    }

    validate_graph(graph)

    graph.pop("start", None)
    return graph


def validate_graph(graph: Dict[str, Any]) -> None:
    nodes = graph.get("nodes") or []
    edges = graph.get("edges") or []

    if not nodes:
        raise ValueError("Graph has no nodes")

    node_ids = [n.get("id") for n in nodes]
    if any(not nid for nid in node_ids):
        raise ValueError("All nodes must have non-empty id")

    start_id = graph.get("start") or node_ids[0]

    node_set = set(node_ids)

    for e in edges:
        src = e.get("from")
        dst = e.get("to")
        if src not in node_set:
            raise ValueError(f"Edge from unknown node: {src}")
        if dst not in node_set:
            raise ValueError(f"Edge to unknown node: {dst}")

    adj: Dict[str, List[str]] = {nid: [] for nid in node_set}
    for e in edges:
        adj[e["from"]].append(e["to"])

    q: deque[str] = deque([start_id])
    reachable: set[str] = set()

    while q:
        cur = q.popleft()
        if cur in reachable:
            continue
        reachable.add(cur)
        for nxt in adj.get(cur, []):
            if nxt not in reachable:
                q.append(nxt)

    unreachable = sorted(node_set - reachable)
    if unreachable:
        raise ValueError("Unreachable node(s): " + ", ".join(unreachable))


def graph_to_dot(graph: Dict[str, Any]) -> str:
    def esc(s: str) -> str:
        return s.replace("\\", "\\\\").replace('"', "\\\"")

    nodes = graph.get("nodes") or []
    edges = graph.get("edges") or []

    lines: List[str] = ["digraph Dialogue {", "  rankdir=LR;"]

    for n in nodes:
        nid = n.get("id", "")
        ntype = n.get("type", "")
        speaker = n.get("speaker", "")
        text = n.get("text", "")

        if ntype == "choice":
            shape = "diamond"
        elif ntype == "end" or nid == "End":
            shape = "doublecircle"
        else:
            shape = "box"

        label_parts = [nid]
        if speaker:
            label_parts.append(speaker + ":")
        if text:
            label_parts.append(text)
        label = "\\n".join(label_parts)

        lines.append(f'  "{esc(nid)}" [shape={shape}, label="{esc(label)}"];')

    for e in edges:
        src = e.get("from", "")
        dst = e.get("to", "")
        etext = e.get("text", "")
        if etext:
            lines.append(f'  "{esc(src)}" -> "{esc(dst)}" [label="{esc(etext)}"];')
        else:
            lines.append(f'  "{esc(src)}" -> "{esc(dst)}";')

    lines.append("}")
    return "\n".join(lines) + "\n"


def _main() -> None:
    script_path = "/app/script.txt"
    json_path = "/app/dialogue.json"
    dot_path = "/app/dialogue.dot"

    with open(script_path, "r", encoding="utf-8") as f:
        text = f.read()

    graph = parse_script(text)

    with open(json_path, "w", encoding="utf-8") as f:
        json.dump(graph, f, indent=2, ensure_ascii=False)
        f.write("\n")

    dot_text = graph_to_dot(graph)
    with open(dot_path, "w", encoding="utf-8") as f:
        f.write(dot_text)


if __name__ == "__main__":
    _main()
